package com.kuaixietech.commerce;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.kuaixietech.insurance.InsuranceSelections;
import com.kuaixietech.security.DomainAccessGuard;
import com.kuaixietech.service.finance.impl.AtomicMoneyService;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.commerce.ProductCheckoutModels.*;
class ProductCheckoutTest {
 final String productId="123e4567-e89b-42d3-a456-426614174000",tripId="223e4567-e89b-42d3-a456-426614174000",requestId="323e4567-e89b-42d3-a456-426614174000";
 JdbcTemplate db;DomainAccessGuard guard;AtomicMoneyService money;InsuranceSelections insurance;ProductCheckoutService service;Map<String,Object> product,trip,reservation;List<String> writes;List<Object[]> arguments;int reserved;
 @BeforeEach void init(){db=mock(JdbcTemplate.class);guard=mock(DomainAccessGuard.class);money=mock(AtomicMoneyService.class);insurance=mock(InsuranceSelections.class);writes=new ArrayList<>();arguments=new ArrayList<>();reserved=0;
  product=new HashMap<>(Map.of("id",productId,"owner_id","seller","name","Camera","price",new BigDecimal("10.01"),"stock",3,"image_urls","[]","status","on","carrier_verify_status","approved"));trip=new HashMap<>(Map.of("id",tripId,"owner_id","seller","capacity_qty",10,"remaining_slots",10,"return_date",LocalDate.now().plusDays(2),"carry_mode","solo"));
  when(guard.requireVerifiedBuyer()).thenReturn("buyer");when(money.lockBalance("buyer")).thenReturn(new BigDecimal("1000"));when(money.addBalance(any(),any(),any(),any(),any())).thenReturn(new BigDecimal("978.98"));
  when(db.queryForList(anyString(),any(Object[].class))).thenAnswer(call->{String sql=call.getArgument(0);if(sql.startsWith("SELECT owner_id FROM t_products"))return List.of(Map.of("owner_id",product.get("owner_id")));if(sql.startsWith("SELECT id FROM t_profiles"))return List.of(Map.of("id","profile"));if(sql.startsWith("SELECT r.request_hash"))return reservation==null?List.of():List.of(reservation);if(sql.startsWith("SELECT p.id,p.owner_id"))return List.of(new HashMap<>(product));if(sql.startsWith("SELECT id,owner_id,capacity_qty"))return List.of(new HashMap<>(trip));if(sql.startsWith("SELECT id,owner_id,status FROM t_stores"))return List.of(Map.of("id","store","owner_id","seller","status",product.get("store_status")));return List.of();});
  when(db.queryForObject(anyString(),eq(Integer.class),any(Object[].class))).thenAnswer(call->reserved);when(db.queryForObject(anyString(),eq(Boolean.class),any(Object[].class))).thenReturn(true);
  when(db.update(anyString(),any(Object[].class))).thenAnswer(call->{String sql=call.getArgument(0);Object[] args=(Object[])call.getRawArguments()[1];writes.add(sql);arguments.add(args);if(sql.startsWith("UPDATE t_products SET stock=stock-")){int next=((Number)product.get("stock")).intValue()-((Number)args[0]).intValue();if(next<0)return 0;product.put("stock",next);}if(sql.startsWith("INSERT INTO t_product_order_reservations"))reservation=new HashMap<>(Map.of("buyer_id",args[2],"request_hash",args[10],"status","requesting"));assertEquals(sql.chars().filter(c->c=='?').count(),args.length,"SQL binds must match placeholders");return 1;});
  service=new ProductCheckoutService(db,guard,money,insurance,new ObjectMapper(),24);
 }
 Input input(String fingerprint,BigDecimal unit,BigDecimal escrow){return new Input(productId,tripId,2,"Buyer","13800138000","Address",null,null,"waived",null,requestId,unit,escrow,fingerprint);}
 Input confirmed(){var q=service.quote(input(null,null,null));return input(q.productFingerprint(),new BigDecimal(q.unitPrice()),new BigDecimal(q.buyerEscrow()));}
 void code(String expected,Runnable work){var error=assertThrows(ResponseStatusException.class,work::run);assertEquals(expected,error.getReason());}
 @Test void serverQuoteUsesCatalogAmountWithoutPlatformPremium(){var q=service.quote(input(null,null,null));assertEquals("20.02",q.goodsAmount());assertEquals("1.00",q.serviceFee());assertEquals("21.02",q.buyerEscrow());assertEquals("0.00",q.insurancePremium());assertEquals(24,q.intentHours());assertTrue(q.productFingerprint().matches("[a-f0-9]{64}"));assertTrue(writes.isEmpty());verifyNoInteractions(money,insurance);}
 @Test void callerCannotOrderOwnProduct(){product.put("owner_id","buyer");code("CANNOT_ORDER_OWN_PRODUCT",()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
 @Test void uppercaseStoredOwnerCannotBypassSelfTradeGuard(){String buyer="123e4567-e89b-42d3-a456-426614174000";when(guard.requireVerifiedBuyer()).thenReturn(buyer);product.put("owner_id",buyer.toUpperCase(Locale.ROOT));code("CANNOT_ORDER_OWN_PRODUCT",()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
 @Test void pausedStoreCannotAcceptProductOrder(){product.put("store_id","store");product.put("store_status","paused");product.put("store_owner","seller");code("PRODUCT_STORE_UNAVAILABLE",()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
 @Test void singleRequestReservesStockAndEscrowExactlyOnce(){var input=confirmed();var result=service.create(input);service.create(input);assertEquals("requesting",result.get("status"));assertEquals(1,product.get("stock"));assertEquals(1,writes.stream().filter(s->s.startsWith("UPDATE t_products SET stock=stock-")).count());verify(money,times(1)).addBalance(eq("buyer"),eq(new BigDecimal("-21.02")),eq("deposit_freeze"),eq(result.get("id")),any());assertEquals(1,writes.stream().filter(s->s.startsWith("INSERT INTO t_deposits")).count());}
 @Test void confirmedReplayStillWorksAfterProductIsHidden(){var input=confirmed();service.create(input);product.put("status","off");reservation.put("status","purchased");assertEquals("purchased",service.create(input).get("status"));verify(money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void reusedRequestCannotChangeGoodsOrRecipient(){var input=confirmed();service.create(input);var changed=new Input(productId,tripId,2,"Another buyer","13800138000","Address",null,null,"waived",null,requestId,input.expectedUnitPrice(),input.expectedBuyerEscrow(),input.expectedProductFingerprint());code("PRODUCT_ORDER_REQUEST_REUSED",()->service.create(changed));verify(money,times(1)).addBalance(any(),any(),any(),any(),any());}
 @Test void catalogPriceChangeCannotUseOldConfirmation(){var input=confirmed();product.put("price",new BigDecimal("10.02"));code("PRODUCT_CHANGED_REQUOTE",()->service.create(input));assertTrue(writes.isEmpty());verify(money,never()).addBalance(any(),any(),any(),any(),any());}
 @Test void samePriceDifferentItemRequiresNewConfirmation(){var input=confirmed();product.put("name","Different item");code("PRODUCT_CHANGED_REQUOTE",()->service.create(input));assertTrue(writes.isEmpty());}
 @Test void changedOriginRequiresNewConfirmation(){var input=confirmed();product.put("region","another origin");code("PRODUCT_CHANGED_REQUOTE",()->service.create(input));assertTrue(writes.isEmpty());}
 @Test void buyerVerificationIsRecheckedAfterWaitingForProfileLocks(){var input=confirmed();when(guard.requireVerifiedBuyer()).thenReturn("buyer").thenThrow(new org.springframework.security.access.AccessDeniedException("revoked"));assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.create(input));assertTrue(writes.isEmpty());verify(money,never()).addBalance(any(),any(),any(),any(),any());}
 @Test void insufficientBalanceCannotDecrementStock(){var input=confirmed();when(money.lockBalance("buyer")).thenReturn(new BigDecimal("21.01"));code("INSUFFICIENT_BALANCE",()->service.create(input));assertEquals(3,product.get("stock"));assertTrue(writes.isEmpty());}
 @Test void insufficientStockOrTripCapacityRejectsBeforeMutation(){var input=confirmed();product.put("stock",1);code("PRODUCT_STOCK_UNAVAILABLE",()->service.create(input));product.put("stock",3);reserved=9;code("TRIP_CAPACITY_UNAVAILABLE",()->service.create(input));assertTrue(writes.isEmpty());}
 @Test void categoryIsCheckedAgainAfterProductLock(){product.put("category_id",1L);var input=confirmed();when(db.queryForObject(anyString(),eq(Boolean.class),any(Object[].class))).thenReturn(true,false);code("CATEGORY_NOT_ALLOWED_FOR_TRIP",()->service.create(input));assertTrue(writes.isEmpty());}
 @Test void uncategorizedProductCannotBypassRestrictedTripCategories(){when(db.queryForList(startsWith("SELECT category_id FROM t_trip_categories"),any(Object[].class))).thenReturn(List.of(Map.of("category_id",1)));code("CATEGORY_REQUIRED_FOR_TRIP",()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
 @Test void poolTripsAreNotSilentlySoldAsUnassignedSoloOrders(){trip.put("carry_mode","pool");code("PRODUCT_TRIP_UNAVAILABLE",()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
 @Test void expectedDeliveryCannotPrecedeReturn(){var input=new Input(productId,tripId,1,"Buyer","13800138000","Address",LocalDate.now().plusDays(1),null,"waived",null,null,null,null,null);code("PRODUCT_EXPECTED_DATE_BEFORE_TRIP_RETURN",()->service.quote(input));}
 @Test void profilesAreLockedInStableOrderBeforeTripAndStock(){service.create(confirmed());var sequence=inOrder(db);sequence.verify(db).queryForList(eq("SELECT owner_id FROM t_products WHERE id=?"),eq(productId));sequence.verify(db).queryForList(eq("SELECT id FROM t_profiles WHERE id=? FOR UPDATE"),eq("buyer"));sequence.verify(db).queryForList(eq("SELECT id FROM t_profiles WHERE id=? FOR UPDATE"),eq("seller"));sequence.verify(db).queryForList(startsWith("SELECT r.request_hash"),any(Object[].class));sequence.verify(db).queryForList(argThat(s->s.startsWith("SELECT id,owner_id,capacity_qty")&&s.endsWith("FOR UPDATE")),eq(tripId),eq("seller"),eq(productId));sequence.verify(db).queryForList(argThat(s->s.startsWith("SELECT p.id,p.owner_id")&&s.endsWith("FOR UPDATE")),eq(productId));}
 @Test void maximumTotalAmountUsesExistingBackendPolicy(){product.put("price",new BigDecimal("600000.00"));assertThrows(IllegalArgumentException.class,()->service.quote(input(null,null,null)));assertTrue(writes.isEmpty());}
}
